// Add f_ module to parent patcher.
// f_addmod.js runs inside f_modules.maxpat, which is a bpatcher directly
// in the user's patch — so we need one level up.

// Authoritative presentation sizes [w, h] keyed by bare module name: each module's presentation
// panel rect, plus the overrides in src/f_modules/menu.py (build/generate_menu.py writes this block).
// BEGIN SIZES (generated by build/generate_menu.py from src/f_modules/menu.py; do not hand-edit)
var SIZES = {
    "chladni":        [299, 234],
    "grain":          [232, 176],
    "ks":             [190, 110],
    "masonry":        [342, 241],
    "quasi":          [227, 164],
    "vf_seeds":       [190, 205],
    "stipple":        [191, 157],
    "weave":          [220, 219],
    "wc":             [272, 150],
    "droste":         [150,  89],
    "lens":           [231, 156],
    "mobius":         [185,  90],
    "ngon":           [154,  91],
    "sirds":          [190, 130],
    "stereo":         [160,  90],
    "channel_grader": [150, 165],
    "hue_processor":  [150, 120],
    "luma_processor": [150, 120],
    "tone_curve":     [150, 120],
    "vf_flow":        [150,  80],
    "vf_fluid":       [190, 150],
    "vf_immiscible":  [190, 150],
    "vf_lbm":         [197, 110],
    "vf_optical_flow":[190, 130],
    "vf_repulse":     [165,  80],
    "vf_vortex":      [196, 160],
    "vf_vortex_multi":[191, 284],
    "vf_vorticity":   [133,  80],
    "vf_advect":      [190, 150],
    "caustic":        [227, 122],
    "vf_chroma":      [190, 180],
    "vf_glow":        [190, 120],
    "vf_prism":       [190, 160],
    "vf_streak":      [190, 100],
    "vf_warp":        [ 78,  90],
    "tf_tensormap":   [154,  84],
    "tf_smooth":      [154,  84],
    "tf_sharpen":     [154,  84],
    "tf_aniso_blur":  [190,  90],
    "tf_glyph":       [190, 150],
    "tf_hatch":       [190, 150],
    "tf_axisflow":    [154,  90],
    "vf_fieldmap":    [150,  88],
    "vf_potential":   [190, 100],
    "vf_split":       [ 80,  80],
    "util_matrix_2":  [230, 120],
    "util_profile":   [200, 120],
    "texrouter":      [213, 130]
};
// END SIZES

// BEGIN RECIPES (generated by build/generate_menu.py from src/f_modules/menu.py; do not hand-edit)
var RECIPES = {
    "fieldmap_seeds": ["vf_fieldmap", "vf_seeds"],
    "fieldmap_streak": ["vf_fieldmap", "vf_streak"],
    "fluid_caustic": ["ngon", "vf_fieldmap", "vf_fluid", "caustic"],
    "chladni_glow": ["chladni", "vf_fieldmap", "vf_glow"],
    "grain_warp": ["grain", "vf_fieldmap", "vf_warp"],
    "masonry_repulse": ["masonry", "vf_repulse", "vf_advect"],
    "motion_prism": ["masonry", "vf_optical_flow", "vf_prism"],
    "ngon_flow": ["ngon", "vf_flow", "vf_advect"],
    "repulse_caustic": ["vf_repulse", "caustic", "lens"],
    "sirds": ["grain", "sirds", "stereo"],
    "tensor_advect": ["tf_tensormap", "tf_axisflow", "vf_advect"],
    "vorticity_fluid": ["vf_fieldmap", "vf_fluid", "vf_vorticity"]
};
// END RECIPES

// Place one module's bpatcher in the user's patch at (x, y); returns its width.
function place(target, mod, x, y) {
    var size = SIZES[mod] || [200, 150]; // fallback if a new module isn't listed yet
    var myobj = target.newobject("bpatcher");
    target.bringtofront(myobj);
    myobj.message("bgmode", 1);
    myobj.message("border", 0);
    myobj.replace("f_" + mod + ".maxpat");
    myobj.rect = [x, y, x + size[0], y + size[1]];
    return size[0];
}

function addmod(mod) {
    var loc = this.patcher.box.rect; // f_modules bpatcher coords in user's patch
    var offset = 85;
    place(this.patcher.parentpatcher, mod, loc[0] + offset, loc[1]);
}

// A recipe is a row of modules, left to right in signal order. Nothing is wired: each module is
// placed where addmod would put it, side by side.
function addrecipe(key) {
    var mods = RECIPES[key];
    if (!mods) { post("f_addmod: no recipe named " + key + "\n"); return; }
    var loc = this.patcher.box.rect;
    var target = this.patcher.parentpatcher;
    var x = loc[0] + 85;
    for (var i = 0; i < mods.length; i++) x += place(target, mods[i], x, loc[1]) + 12;
}
